import json
from collections import Counter

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]].
    Returns None on failure (caller degrades gracefully)."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def perceive(observation_history: list[str]) -> str:
    obs = observation_history[-1] if observation_history else ""
    grid = _parse_grid(obs)
    if grid is None:
        # Never return empty – give a minimal non-empty string
        return "no_grid"

    # Determine background colour (most common cell colour)
    all_colours = [cell for row in grid for cell in row]
    if not all_colours:
        return "empty_grid"
    colour_counts = Counter(all_colours)
    background = colour_counts.most_common(1)[0][0]  # most frequent

    # Collect non-background cells
    features = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != background:
                features.append(f"{r},{c}:{colour}")

    if not features:
        # Should not happen in typical worlds, but fallback
        return "no_objects"

    # Concatenate, ensure length <= 2000 (truncate if necessary, but unlikely)
    result = "; ".join(features)
    if len(result) > 1999:
        result = result[:1996] + "..."   # indicate truncation

    return result

