    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if rows == 0 or cols == 0:
        return f"bg:unknown;size:{rows}x{cols};empty_grid"

    # Determine background colour (most common cell colour)
    all_colours = [cell for row in grid for cell in row]
    if not all_colours:
