    non_bg = {}
    for r in range(rows):
        for c in range(cols):
            col = grid[r][c]
            if col != background:
                non_bg[(r, c)] = col

    if not non_bg:
        return f"bg:{background};size:{rows}x{cols};no_objects"

    # For each non-background cell, count orthogonal neighbours of each colour
    parts = [f"bg:{background};size:{rows}x{cols}"]
    for (r, c), colour in sorted(non_bg.items()):
        neighbour_counts = Counter()
        for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                nb_colour = grid[nr][nc]
                if nb_colour != background:
                    neighbour_counts[nb_colour] += 1
        # Build compact adjacency summary
        if neighbour_counts:
            nb_str = "[" + ",".join(f"{cnt}{col}" for col, cnt in neighbour_counts.most_common()) + "]"
        else:
            nb_str = "[]"
        parts.append(f"{r},{c}:{colour}{nb_str}")

    result = "; ".join(parts)
    if len(result) > 1999:
        result = result[:1996] + "..."   # truncation marker
    return result

