def _get_background(grid):
    """Return the most common colour in grid."""
    all_colours = [cell for row in grid for cell in row]
    return Counter(all_colours).most_common(1)[0][0]

def _detect_move(prev_grid, curr_grid, background):
    """
    Detect a single-object move from prev to curr.
    Returns (src_row, src_col, dst_row, dst_col, colour) or None.
    """
    prev_cells = {}
    for r, row in enumerate(prev_grid):
        for c, col in enumerate(row):
            if col != background:
                prev_cells[(r, c)] = col
    curr_cells = {}
    for r, row in enumerate(curr_grid):
        for c, col in enumerate(row):
            if col != background:
                curr_cells[(r, c)] = col

    moves = []
    for (sr, sc), scol in prev_cells.items():
        if (sr, sc) not in curr_cells:
            # source disappeared
            for dr, dc in ((0,1), (0,-1), (1,0), (-1,0)):
                nr, nc = sr + dr, sc + dc
                if (nr, nc) in curr_cells:
                    ncol = curr_cells[(nr, nc)]
                    if ncol == scol:
                        prev_ncol = prev_cells.get((nr, nc), background)
                        if prev_ncol != ncol:
                            moves.append((sr, sc, nr, nc, scol))
    if len(moves) == 1:
        return moves[0]  # (sr, sc, dr, dc, col)
    return None

def perceive(observation_history: list[str]) -> str:
    if not observation_history:
        return "no_history"

    # Parse all grids
    grids = []
    for obs in observation_history:
        g = _parse_grid(obs)
        if g is None:
            return "parse_error"
        grids.append(g)

    curr_grid = grids[-1]
    rows = len(curr_grid)
    cols = len(curr_grid[0]) if rows else 0
    if rows == 0 or cols == 0:
        return f"bg:unknown;size:{rows}x{cols}"

    # Determine background (use current grid)
    bg = _get_background(curr_grid)

    # Track active object from history (last detected move destination)
    active = None
    for i in range(1, len(grids)):
        prev_bg = _get_background(grids[i-1])  # could differ, but usually same
        move = _detect_move(grids[i-1], grids[i], bg)  # use current bg for simplicity
        if move:
            sr, sc, dr, dc, col = move
            active = (dr, dc)  # destination becomes active

    # Build active string
    if active is not None:
        active_str = f"active:{active[0]},{active[1]}"
    else:
        active_str = "active:none"

    # Collect non-background cells with directional neighbour info
    cells = []
    for r in range(rows):
        for c in range(cols):
            colour = curr_grid[r][c]
            if colour == bg:
                continue
            nb_parts = []
            for dr, dc, dir_char in [(0,1,'E'), (0,-1,'W'), (1,0,'S'), (-1,0,'N')]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    nb_col = curr_grid[nr][nc]
                    if nb_col != bg:
                        nb_parts.append(f"{dir_char}:{nb_col}")
