def _build_stack_history(grids, bg):
    """
    Given list of grids, return list of dicts (one per state)
    mapping (r,c) -> top_colour for cells that have a stack.
    Detection is based on moves between consecutive frames.
    """
    stack_history = [{} for _ in range(len(grids))]   # stack at state index i
    for i in range(1, len(grids)):
        prev_grid = grids[i-1]
        curr_grid = grids[i]
        prev_stack = stack_history[i-1].copy()
        curr_stack = {}

        move = _detect_move(prev_grid, curr_grid, bg)
        if move:
            sr, sc, dr, dc, col = move
            # check for stacking: destination in prev had an object
            dest_prev_col = prev_grid[dr][dc]
            if dest_prev_col != bg:
                # The moved object lands on an occupied cell -> stack
                curr_stack[(dr, dc)] = col   # top colour
            # source: if it had a stack, that top has moved away
            if (sr, sc) in prev_stack:
                # The top that moved away is col (since move colour matches top)
                # Remove stack from source, base remains
                # (We do nothing here, because curr_stack only records active stacks)
                pass
        # Carry forward stacks from previous state that are still valid
        for (r, c), top in prev_stack.items():
            if 0 <= r < len(curr_grid) and 0 <= c < len(curr_grid[0]):
                # Cell still exists, colour may have changed under noop etc.
                # For simplicity we keep the stack unless the cell became background
                # or a new stack was already recorded (from move)
                if curr_grid[r][c] != bg and (r, c) not in curr_stack:
                    curr_stack[(r, c)] = top
        # Also check for noop resolution: look for cells that changed colour
        # (can be refined, but for the immediate fix we rely on move detection)
        stack_history[i] = curr_stack
    return stack_history

